function assertNever(x: never): never {
  throw new Error("Kasus tidak ditangani: " + JSON.stringify(x));
}
type Pesanan =
  | { status: "menunggu"; id: number }
  | { status: "dibayar"; id: number; metode: string }
  | { status: "dikirim"; id: number; kurir: string; resi: string };

function tampil(p: Pesanan): string {
  switch (p.status) {
    case "menunggu":
      return `#${p.id} menunggu pembayaran`;
    case "dibayar":
      return `#${p.id} dibayar via ${p.metode}`;
    case "dikirim":
      return `#${p.id} dikirim ${p.kurir} (${p.resi})`;
    default:
      return assertNever(p);
  }
}
const daftar: Pesanan[] = [
  { status: "dibayar", id: 11, metode: "QRIS" },
  { status: "dikirim", id: 12, kurir: "JNE", resi: "JN123" },
];
daftar.forEach((p) => console.log(tampil(p)));

