function assertNever(x: never): never {
  throw new Error("Kasus tidak ditangani: " + JSON.stringify(x));
}
type Tiket =
  | { status: "baru"; id: number }
  | { status: "diproses"; id: number; petugas: string }
  | { status: "selesai"; id: number; solusi: string };
function ringkas(t: Tiket): string {
  switch (t.status) {
    case "baru":
      return `#${t.id} baru`;
    case "diproses":
      return `#${t.id} diproses ${t.petugas}`;
    case "selesai":
      return `#${t.id} selesai: ${t.solusi}`;
    default:
      return assertNever(t);
  }
}
const daftar: Tiket[] = [
  { status: "baru", id: 1 },
  { status: "diproses", id: 2, petugas: "Sari" },
  { status: "selesai", id: 3, solusi: "ganti kabel" },
];
for (const t of daftar) console.log(ringkas(t));
